const assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm');
const source=fs.readFileSync('web/js/48-chat.js','utf8');
const ctx=vm.createContext({chatArtifactSelections:new Map()});vm.runInContext(source.slice(source.indexOf('function chatSelectedArtifacts('),source.indexOf('function chatOpenWorkingArtifact(')),ctx);
const key='chat:alfred/test',first={id:'a',revision:'old',task:'task-one',title:'First'};
ctx.chatArtifactSelections.set(key,first);
ctx.chatAddArtifactSelection(key,{id:'b',revision:'b-one',explicitArtifacts:true});
assert.equal(ctx.chatSelectedArtifacts(ctx.chatArtifactSelections.get(key)).length,2);
assert.equal(ctx.chatArtifactSelections.get(key).task,'task-one');
assert.equal(ctx.chatArtifactPayload(ctx.chatArtifactSelections.get(key)).explicitArtifacts,true);
assert.throws(()=>ctx.chatAddArtifactSelection(key,{id:'x',revision:'x-one',task:'other-task'}),/different tasks/);
assert.equal(ctx.chatSelectedArtifacts(ctx.chatArtifactSelections.get(key)).length,2,'failed add is atomic');
ctx.chatAddArtifactSelection(key,{id:'a',revision:'old',explicitArtifacts:true});
assert.equal(ctx.chatSelectedArtifacts(ctx.chatArtifactSelections.get(key)).length,2,'explicit reselection upgrades existing reference');
assert.equal(ctx.chatSelectedArtifacts(ctx.chatArtifactSelections.get(key))[0].explicitArtifacts,true);
ctx.chatAddArtifactSelection(key,{id:'a',revision:'new',task:'task-one'});
for(let i=3;i<8;i++)ctx.chatAddArtifactSelection(key,{id:'file-'+i,revision:'v'+i});
const full=JSON.stringify(ctx.chatArtifactPayload(ctx.chatArtifactSelections.get(key)));
assert.throws(()=>ctx.chatAddArtifactSelection(key,{id:'ninth',revision:'new'}),/Up to 8/);
assert.equal(JSON.stringify(ctx.chatArtifactPayload(ctx.chatArtifactSelections.get(key))),full,'limit does not replace old choices');
ctx.chatAddArtifactSelection('task:task-one',first);ctx.chatAddArtifactSelection('task:task-one',{id:'second',revision:'v'});
assert.equal(ctx.chatArtifactSelections.get('task:task-one').id,'second','task panel keeps its existing single-reference contract');
console.log('Legacy selection, additive identity, consent upgrade, mixed-task guard and atomic eight-reference limit passed');
